import json, hashlib, sys, html, urllib.request
from pathlib import Path
root=Path(__file__).parent
run=Path((root/'latest.txt').read_text().strip())
data={}
for name in ['recursive','comparison','inference']:
 p=run/name
 source=json.loads((p/'source.json').read_text()); candidates=json.loads((p/'candidates.json').read_text()); checks=json.loads((p/'checks.json').read_text())
 # Preserve the failed request and send a corrected typed state with actual candidate endpoints.
 body=json.loads((p/'observers/laya-request.json').read_text()); body['state']=json.loads(body['state']);body['state']['candidate']=candidates[0];body['questions']['dependency']['instructions']='Does the unchanged source license the exact candidate dependency in the goal? Assess the referenced graph roles, not truth. Choose unresolved if construction evidence is missing.'
 request=urllib.request.Request('http://127.0.0.1:8091/v1/systemone',data=json.dumps(body).encode(),headers={'Content-Type':'application/json'})
 (p/'observers/laya-corrected-request.json').write_text(json.dumps(body,indent=2)+'\n')
 try:
  with urllib.request.urlopen(request,timeout=60) as r: response=json.load(r)
  result={'status':'REJECTED_TRUNCATED' if response.get('usage',{}).get('truncated') else 'COMPLETED','response':response,'semantic_authority':False}
 except Exception as e: result={'status':'FAILED','error':str(e)}
 (p/'observers/laya-corrected-result.json').write_text(json.dumps(result,indent=2)+'\n')
 data[name]={'source':source,'candidates':candidates,'checks':checks,'laya':result}
report='''# Unscaffolded construction search: bounded experiment\n\nThree unchanged source inputs; Qwen initial proposal followed by one feedback proposal per input. No authored semantic graph was supplied. All six proposals contain zero network operands. No candidate has semantic admission.\n\n| Source | Initial | Feedback | Semantic finding |\n|---|---|---|---|\n| Recursive phrase | Passes limited structural checks | Same topology | Separate copulas and subjects merged; no explicit gap/binder/network interior |\n| Aristotle comparison | Rejected | Rejected | Operator contains members; no validated degree comparison |\n| Aristotle inference | Rejected | Rejected | Non-network interiors; feedback adds undeclared member |\n\nPassing the limited JSON checks does not establish grammatical correctness. The recursive candidate demonstrates a missing occurrence-correspondence check. The generic native frontier fixture gate passed separately; it does not validate these natural-language candidates.\n\nThe initial Laya requests failed HTTP 422 because the question lacked required instructions. Corrected requests include instructions, send an object and include the exact candidate; both attempts are retained. Jev selected the initial recursive candidate and unresolved for both Aristotle cases. These are observations, not proofs. Corrected Laya responses exceeded its 512-token context and are rejected as truncated; no Laya result is counted.\n\n## Capability boundary\n\nNative partial graphs, incidence holes, region contraction/expansion and bounded search are available. The inspected restricted semantic-lift adapter supplies seven fixture construction laws. No callable source-grounded WHAT/WHEN/WHERE gap licensing constitution was established. Generic append/nest/enclose meanings in the co-grown specification remain proposed interfaces, not a demonstrated general interpreter.\n\nThe current runner performs two model expansions per source. It is not yet the recursive native agenda in the specification. Higher-order synthesis and backward repair were not demonstrated.\n\nNext implementation: preserve lexical occurrence identities as a compulsory substrate; represent proposed groupings as networks with those occurrences retained; require construction licenses for absent positions; implement the narrow grammatical construction interfaces before calling model ranking a semantic tower.\n'''
(run/'report.md').write_text(report+'\nNative partial storage validation passed for the two recursive proposals. Relations remain unresolved incidence holes, meanings unregistered. Storage validity does not establish grammatical correctness.\n')
payload=json.dumps(data).replace('</','<\\/')
page='''<!doctype html><meta charset="utf-8"><title>Construction search evidence</title><style>body{font:16px system-ui;background:#101820;color:#eee;margin:28px}select,button{padding:8px}pre{white-space:pre-wrap;background:#182630;padding:16px}svg{background:#182630;width:100%;height:540px}text{fill:white;font:12px system-ui}line{stroke:#708da0}circle{fill:#326682}rect{fill:#885c32}a{color:#8dd8ff}</style><h1>Unscaffolded construction search</h1><p>Proposals only. Semantic admission blocked. Relation objects remain visible; no candidate produced a network operand.</p><select id="source"></select> <select id="candidate"></select><p><a href="report.md">Results and capability boundary</a></p><pre id="raw"></pre><svg id="graph" viewBox="0 0 1100 540"></svg><h2>Checks and model evidence</h2><pre id="checks"></pre><h2>Exact candidate JSON</h2><pre id="json"></pre><script>const data=PAYLOAD;const s=document.querySelector('#source'),c=document.querySelector('#candidate');for(const k of Object.keys(data))s.add(new Option(k,k));function pick(){c.innerHTML='';data[s.value].candidates.forEach((x,i)=>c.add(new Option(x.id,i)));draw()}function draw(){const d=data[s.value],a=d.candidates[c.value];document.querySelector('#raw').textContent=d.source.text;document.querySelector('#checks').textContent=JSON.stringify({checks:d.checks[a.id],laya:d.laya},null,2);document.querySelector('#json').textContent=JSON.stringify(a,null,2);const g=document.querySelector('#graph');g.innerHTML='';const pos={};function el(t,attrs,text){const e=document.createElementNS('http://www.w3.org/2000/svg',t);for(const k in attrs)e.setAttribute(k,attrs[k]);if(text)e.textContent=text;g.appendChild(e)}a.objects.forEach((o,i)=>pos[o.id]=[110+i%4*275,90+Math.floor(i/4)*160]);a.relations.forEach((r,i)=>pos[r.id]=[100+i*215,440]);a.relations.forEach(r=>r.ends.forEach(e=>{if(pos[e.target]){const p=pos[r.id],q=pos[e.target];el('line',{x1:p[0],y1:p[1],x2:q[0],y2:q[1]});el('text',{x:(p[0]+q[0])/2,y:(p[1]+q[1])/2},e.role)}}));a.objects.forEach(o=>{const [x,y]=pos[o.id];el('circle',{cx:x,cy:y,r:32});el('text',{x:x-90,y:y-42},o.id+' '+o.kind+': '+o.type);el('text',{x:x-90,y:y+53},o.anchors.join(', '))});a.relations.forEach(r=>{const [x,y]=pos[r.id];el('rect',{x:x-60,y:y-18,width:120,height:36,rx:8});el('text',{x:x-55,y:y+4},r.id+' '+r.family)})}s.onchange=pick;c.onchange=draw;pick();</script>'''.replace('PAYLOAD',payload)
(run/'network.html').write_text(page)
manifest={str(p.relative_to(run)):hashlib.sha256(p.read_bytes()).hexdigest() for p in run.rglob('*') if p.is_file() and p.name!='manifest.json'}
(run/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(run/'network.html')
